'use strict';
// Isolated prototype: fictional profiles and browser-local state only. No real authentication or API.
const $=(s,r=document)=>r.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const copy={home:['首頁','Home'],people:['探索人物','Discover'],journal:['人物誌','Journal'],tv:['SHE TV','SHE TV'],events:['活動','Gatherings'],join:['加入 SHE','Join SHE'],workspace:['我的工作台','My studio'],language:['語言','Language'],preview:['獨立互動測試版・所有人物與數據為示意','Independent prototype · Illustrative profiles & data'],guide:['測試指南','Test guide'],save:['儲存草稿','Save draft'],submit:['送交審核','Submit for review'],name:['公開顯示名稱','Public display name'],email:['測試 Email','Test email'],next:['下一步','Continue'],back:['上一步','Back'],cancel:['取消','Cancel'],close:['關閉','Close'],follow:['追蹤','Follow'],following:['已追蹤','Following'],bookmark:['收藏','Save'],saved:['已收藏','Saved'],share:['分享','Share'],report:['檢舉','Report'],all:['全部','All'],entrepreneur:['企業家','Entrepreneur'],contestant:['佳麗','Pageant talent'],creator:['創作者','Creator'],professional:['專業人士','Professional'],demo:['示意人物・非真實會員','Illustrative profile · Not a real member'],draft:['草稿','Draft'],review:['送審中','In review'],changes:['需修改','Changes requested'],published:['已發布','Published'],withdrawn:['已撤下','Withdrawn'],location:['公開所在地','Public location'],bio:['個人介紹','Biography'],headline:['專業標題','Headline'],country:['國籍（不公開）','Nationality (private)'],residence:['居住地','Country of residence'],timezone:['時區','Time zone'],phone:['聯絡電話（選填，不公開）','Phone (optional, private)'],role:['人物身分','Profile roles'],original:['原文姓名','Original name'],url:['公開網址代稱','Public URL slug'],mainlang:['主要內容語言','Primary content language'],invitations:['合作邀請','Invitations'],settings:['帳號與隱私','Account & privacy'],content:['內容管理','Content'],profile:['編輯專頁','Edit profile'],overview:['經營總覽','Overview'],admin:['審核模擬','Review sandbox'],spec:['系統規格','System blueprint'],accept:['接受','Accept'],decline:['婉拒','Decline'],more:['要求補充','Ask for details'],block:['封鎖','Block'],accepted:['已接受','Accepted'],declined:['已婉拒','Declined'],details:['待補充','Awaiting details'],blocked:['已封鎖','Blocked'],pending:['待處理','Pending'],send:['送出模擬邀請','Send demo invitation'],required:['請完成必填欄位。','Please complete the required fields.'],local:['資料僅儲存在此瀏覽器；請使用虛構資料，不要輸入證件或密碼。','Stored in this browser only. Use fictional information. Do not enter identity documents or passwords.'],unconnected:['待正式串接','Not connected'],on:['開啟','On'],off:['關閉','Off'],motion:['減少動態','Reduce motion'],reset:['重設測試資料','Reset demo data'],logout:['結束模擬登入','End demo session'],empty:['目前沒有內容','Nothing here yet'],public:['公開','Public'],private:['私人','Private'],previewpage:['預覽專頁','Preview profile'],editorial:['編輯式人物誌','Editorial'],portfolio:['作品集','Portfolio'],service:['專業服務','Professional'],view:['查看','View'],verification:['本人自述・未查核','Self-reported · Unverified'],read:['閱讀故事','Read story'],search:['搜尋姓名、專業或關鍵字','Search name, expertise or keyword'],clear:['清除篩選','Clear filters'],edit:['編輯','Edit'],activity:['最新動態','Latest updates'],privacy:['隱私與使用說明','Privacy & terms'],test:['測試','Demo'],download:['下載規劃文件','Download blueprint'],gallery:['作品集','Selected work'],contact:['邀請合作','Invite to collaborate']};
const bi=(zh,en)=>state.lang==='en'?en:zh;
const t=k=>copy[k]?copy[k][state.lang==='en'?1:0]:k;
const defaults={lang:'zh-Hant',motion:false,session:false,step:0,reg:{name:'',email:'',roles:[],consents:{}},follows:[],bookmarks:[],tab:'overview',status:'draft',draft:{name:'Your name',original:'',slug:'my-story',headline:'',bioZh:'',bioEn:'',location:'',nationality:'',timezone:'Asia/Taipei',template:'editorial',roles:['entrepreneur'],mainlang:'zh-Hant',modules:['story','gallery','contact']},publishedProfile:null,invitations:[],posts:[],audit:[],filters:{q:'',role:'all',language:'all',sort:'editorial'}};
let stored={};try{stored=JSON.parse(localStorage.getItem('she-preview-v1')||'{}')}catch{}
let state={...structuredClone(defaults),...stored,filters:{...defaults.filters,...stored.filters}};
let route=parseHash();let heroIndex=0;let heroPaused=false;let modalLastFocus;let toastTimer;
const people=[
{id:'aria',name:'Aria Chen',role:'entrepreneur',place:'Taipei',lang:'zh-Hant',img:2,title:['以風格，創造自己的事業。','Building a business with a point of view.'],bio:['從創意到品牌，用自己的步調建立事業，也為更多女性打開可能。此內容為版型與互動示意。','From creative ideas to a brand of her own. An illustrative story about purpose, craft and possibility.'],tags:['Brand strategy','Creative leadership']},
{id:'elena',name:'Elena Laurent',role:'contestant',place:'Paris',lang:'en',img:0,title:['美，是讓世界聽見妳。','Beauty with a voice. Purpose with a platform.'],bio:['以作品、文化交流與公益倡議，分享舞台之外的自己。參賽經歷為本人自述欄位示意，並非官方認證。','A portfolio of creative work, cultural exchange and personal advocacy. Pageant history is a self-reported example, not an official credential.'],tags:['Advocacy','Fashion']},
{id:'maya',name:'Maya Sato',role:'creator',place:'Tokyo',lang:'en',img:3,title:['把日常，寫成自己的風格。','Finding extraordinary in the everyday.'],bio:['透過影像與文字，記錄關於女性、城市與生活的靈感。此為虛構創作者專頁示意。','An illustrative creator exploring women, cities and everyday inspiration through images and words.'],tags:['Visual storytelling','Culture']},
{id:'sofia',name:'Sofia Rivera',role:'professional',place:'Barcelona',lang:'en',img:1,title:['讓專業，成為被看見的力量。','Expertise that opens new possibilities.'],bio:['分享專業觀點、講座與跨文化合作的可能。所有服務與合作案例均為測試示意。','An illustrative professional profile for speaking, sharing expertise and cross-cultural collaboration. All services are examples.'],tags:['Speaking','Consulting']},
{id:'isabel',name:'Isabel Moreno',role:'contestant',place:'Mexico City',lang:'en',img:4,title:['舞台之外，故事正開始。','Beyond the stage, a new story begins.'],bio:['探索時尚、表演與公益，建立能持續成長的個人品牌。這是測試用人物，不代表任何真實佳麗。','Exploring fashion, performance and advocacy through an evolving personal brand. This profile does not represent a real contestant.'],tags:['Performance','Community']},
{id:'lin',name:'Lin Wei',role:'entrepreneur',place:'Singapore',lang:'en',img:5,title:['以自己的視野，連結世界。','A personal vision. An international perspective.'],bio:['以品牌經營與交流合作，連結不同城市的創意與女性觀點。此人物與內容均為示意。','An illustrative profile connecting creative ideas and women’s perspectives across cities.'],tags:['Entrepreneurship','Design']}
];
const storyTitles=[['她的品牌，從一個相信開始','A brand begins with something worth believing in'],['舞台之外，如何持續經營自己','Building a personal brand beyond the stage'],['跨越城市，讓合作有新的可能','New conversations across cities and cultures']];
function persist(){try{localStorage.setItem('she-preview-v1',JSON.stringify(state))}catch{toast(bi('瀏覽器儲存空間不可用；本次變更仍可繼續測試。','Browser storage unavailable. You can continue this session.'))}}
function parseHash(){const p=new URLSearchParams(location.hash.slice(1));return{page:p.get('page')||'home',id:p.get('id')||'',tab:p.get('tab')||'overview'}}
function href(page,id='',tab=''){const p=new URLSearchParams({page});if(id)p.set('id',id);if(tab)p.set('tab',tab);return'#'+p.toString()}
function go(page,id='',tab=''){const h=href(page,id,tab);if(location.hash===h){route=parseHash();render();window.scrollTo(0,0)}else location.hash=h}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4000)}
function audit(action){state.audit.unshift({action,time:new Date().toISOString()});state.audit=state.audit.slice(0,30)}
function image(n,extra=''){return`<img src="/assets/portrait-${Number(n)}.jpg" alt="${esc(bi('品牌形象示意照片','Illustrative brand portrait'))}" ${extra}>`}
function button(label,action,cls='btn',extra=''){return`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`}
function header(){return`<div class="preview">${t('preview')}<a href="${href('guide')}">${t('guide')} ↗</a></div><header class="top"><div class="wrap nav"><a class="brand" href="${href('home')}" aria-label="SHE Home">SHE<small>HER STORY. HER WORLD.</small></a><nav class="navlinks" aria-label="${bi('主要導覽','Main navigation')}">${['people','journal','tv','events'].map(p=>`<a href="${href(p)}" ${route.page===p?'aria-current="page"':''}>${t(p)}</a>`).join('')}</nav><div class="navtools"><div class="lang" role="group" aria-label="${t('language')}"><button data-action="lang" data-lang="zh-Hant" aria-pressed="${state.lang==='zh-Hant'}">繁中</button><span aria-hidden="true">/</span><button data-action="lang" data-lang="en" aria-pressed="${state.lang==='en'}">EN</button></div><a class="navjoin" href="${href(state.session?'studio':'join')}">${state.session?t('workspace'):t('join')} ↗</a><button class="menu-button" data-action="menu" aria-expanded="false" aria-label="${bi('開啟導覽','Open menu')}">☰</button></div></div></header>`}
function footer(){return`<footer class="site-footer wrap"><div class="foot-top"><a href="${href('home')}" class="brand">SHE<small>HER STORY. HER WORLD.</small></a><div class="footlinks"><a href="${href('people')}">${t('people')}</a><a href="${href('studio')}">${t('workspace')}</a><a href="${href('spec')}">${t('spec')}</a><a href="${href('privacy')}">${t('privacy')}</a><button data-action="motion" aria-pressed="${state.motion}">${t('motion')} ${state.motion?'✓':'○'}</button></div></div><div class="foot-bottom"><span>© SHE · INTERNATIONAL WOMEN & CULTURE · ${bi('獨立測試版','INDEPENDENT PREVIEW')}</span><span>${bi('未連接正式會員、交易或 FOBI 系統','No live accounts, transactions or FOBI integration')}</span></div></footer>`}
function heading(k,title,desc=''){return`<div class="page-heading"><span class="eyebrow">${k}</span><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>`}
function sectionTitle(en,zh,desc,link=''){return`<div class="section-head"><div><span class="eyebrow">SHE / ${en}</span><h2>${bi(`<span class="zh">${zh}</span>`,en)}</h2>${desc?`<p>${desc}</p>`:''}</div>${link}</div>`}
function personCard(p){const followed=state.follows.includes(p.id);return`<article class="person-card"><div class="person-photo"><a href="${href('person',p.id)}" aria-label="${t('view')} ${p.name}">${image(p.img,'loading="lazy"')}</a><span class="tag">${t(p.role)}</span><button class="follow" data-action="follow" data-id="${p.id}" aria-pressed="${followed}" aria-label="${followed?t('following'):t('follow')} ${p.name}">${followed?'✓':'+'}</button></div><div class="person-meta"><small>${esc(p.place.toUpperCase())} / ${p.lang==='en'?'EN':'繁中'}</small><a href="${href('person',p.id)}"><h3>${p.name}</h3></a><p>${bi(...p.title)}</p></div></article>`}
function hero(){const p=people[heroIndex];return`<div class="hero reveal"><div class="hero-copy"><span class="eyebrow">THE WOMEN WHO DEFINE THEIR WORLD</span><h1>${bi('她的故事，<br>世界的下一頁。','Her story.<br><em>A world of possibility.</em>')}</h1><p>${bi('從事業到舞台，從個人風格到世界視野。認識她、追蹤她，也讓世界看見妳。','From business to the world stage. Discover remarkable perspectives, follow new voices, and make room for your own.')}</p><div class="hero-actions"><a class="btn" href="${href('people')}">${t('people')} <span>↗</span></a><a class="textlink" href="${href('join')}">${bi('寫下妳的篇章','Begin your own chapter')} ↗</a></div></div><div class="hero-media">${image(p.img,'fetchpriority="high"')}<span class="hero-number">0${heroIndex+1} / 06</span><a href="${href('person',p.id)}" class="hero-note"><small>${bi('本期封面 / 形象示意','THE COVER / ILLUSTRATIVE')}</small><h2>${p.name}</h2><span style="font-size:11px">${t(p.role)} · ${p.place} ↗</span></a><div class="hero-controls"><button data-action="hero-prev" aria-label="${bi('上一張封面','Previous cover')}">←</button><button data-action="hero-pause" aria-pressed="${heroPaused}" aria-label="${bi('暫停或播放動態','Pause or resume motion')}">${heroPaused?'▷':'Ⅱ'}</button><button data-action="hero-next" aria-label="${bi('下一張封面','Next cover')}">→</button></div></div></div>`}
function home(){return`<div class="wrap"><div class="masthead"><div class="issue"><span>${bi('國際女性・風格・事業','WOMEN · CULTURE · POSSIBILITY')}</span><span>${bi('中英文概念刊 / 01','BILINGUAL CONCEPT EDITION / 01')}</span><span>TAIPEI / THE WORLD</span></div><div class="wordmark" aria-label="SHE">SHE<span>HER STORY.<br>HER WORLD.<br>OUR NEXT CHAPTER.</span></div></div><div id="hero-slot">${hero()}</div><div class="ticker"><span>WOMEN IN BUSINESS <b>✧</b></span><span>BEYOND THE STAGE <b>✧</b></span><span>CULTURE & CREATIVITY <b>✧</b></span><span>CONNECTIONS THAT MATTER</span></div><section class="section">${sectionTitle('The women','她們，正在創造自己的世界',bi('不同的起點，同樣值得被看見。','Different beginnings. Stories worth discovering.'),`<a class="textlink" href="${href('people')}">${bi('探索所有人物','Meet all voices')} ↗</a>`)}<div class="people-grid">${people.slice(0,4).map(personCard).join('')}</div><p class="demo-note">${t('demo')} · ${bi('姓名、城市、經歷與照片搭配均為版型示意。','Names, locations, histories and portrait pairings are illustrative.')}</p></section><section class="feature"><div class="feature-photo">${image(4,'loading="lazy"')}</div><div class="feature-copy"><span class="eyebrow">THE EDIT / BEYOND THE STAGE</span><h2>${bi('舞台落幕之後，<br>妳的影響力仍在繼續。','Beyond the spotlight.<br>A story that keeps evolving.')}</h2><p>${bi('將作品、專業與公益理念，整理成屬於自己的國際人物專頁。每個新篇章，都有被看見的入口。','Bring your work, expertise and causes together in a personal profile that grows with you. A place for every new chapter.')}</p><a class="textlink" href="${href('person','elena')}">${bi('探索作品集專頁','Explore a portfolio profile')} ↗</a></div></section><section class="section">${sectionTitle('The journal','今日焦點',bi('關於女性、創意與事業的新觀點。以下為示範文章。','Fresh perspectives on women, creativity and business. Example stories.'))}<div class="story-grid">${storyTitles.map((s,i)=>`<article class="story"><span class="index">0${i+1}</span><span class="eyebrow">${['BRAND & BUSINESS','IDENTITY & PURPOSE','CULTURE & CONNECTION'][i]}</span><a href="${href('article',String(i))}"><h3>${bi(...s)}</h3></a><p>${bi('每一段經歷，都能成為與世界對話的起點。閱讀這篇編輯版型示範。','Every experience can open a new conversation. Explore this editorial layout example.')}</p><footer>SHE EDITORIAL · ${bi('示範內容','DEMO CONTENT')} · 2026.10.24</footer></article>`).join('')}</div></section><section class="section rule">${sectionTitle('In her own words','她，親自說',bi('短篇訪談的視覺與字幕體驗。','A short-form interview and caption concept.'),`<a class="textlink" href="${href('tv')}">SHE TV ↗</a>`)}<div class="video-grid">${[0,1,2].map(videoCard).join('')}</div></section><section class="section rule">${sectionTitle('Coming together','讓相遇，成為新的可能',bi('活動內容及名額皆為介面示意。','Illustrative gatherings, without live booking.'))}${eventRows()}</section><div class="join-panel"><div><span class="eyebrow" style="color:#d1bba0">YOUR NEXT CHAPTER</span><h2>${bi('世界，值得看見妳。','Make room for your story.')}</h2><p>${bi('從一頁專屬人物誌開始，讓故事、作品與每一次合作，都有自己的位置。','A home for your story, your work, and the connections that come next.')}</p></div><a class="btn" href="${href('join')}">${bi('建立我的專頁','Create my profile')} ↗</a></div></div>`}
function videoCard(i){const p=people[i];return`<button class="video-card" data-action="video" data-id="${i}">${image(p.img,'loading="lazy"')}<span class="play" aria-hidden="true">▷</span><div class="video-caption"><small>IN HER OWN WORDS / ${bi('動態示意','MOTION CONCEPT')}</small><h3>${bi(...p.title)}</h3></div></button>`}
function eventRows(){return[0,1].map((i)=>`<div class="event-row"><div class="day">0${i+1}</div><div><span class="eyebrow" style="margin-bottom:5px">SHE CIRCLE / ${bi('活動概念','EVENT CONCEPT')}</span><h3>${i===0?bi('她的品牌・國際女性交流沙龍','Her brand · A conversation across cultures'):bi('從作品到合作・個人品牌工作坊','From portfolio to opportunity · A brand workshop')}</h3><p>${bi('時間與城市待公告・無真實報名或收款','Date and city to be announced · No live booking or payment')}</p></div>${button(bi('接收活動消息','Get event updates'),'event','btn outline',`data-id="${i}"`)}</div>`).join('')}
function discover(followed=false){const f=state.filters;let list=people.filter(p=>(!followed||state.follows.includes(p.id))&&(f.role==='all'||p.role===f.role)&&(f.language==='all'||p.lang===f.language)&&[p.name,p.place,p.title.join(' '),p.tags.join(' '),t(p.role)].join(' ').toLowerCase().includes(f.q.toLowerCase()));if(f.sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));return`<div class="wrap">${heading('THE DIRECTORY',followed?bi('我的關注','My following'):bi('每一位她，都有自己的世界。','A world of women. A world of stories.'),bi('認識企業家、佳麗、創作者與專業人士。人物與經歷皆為測試示意。','Meet entrepreneurs, pageant talent, creators and professionals. All profiles and histories are illustrative.'))}<div class="tabs"><a class="pill ${!followed?'active':''}" href="${href('people')}">${bi('探索人物','Discover')}</a><a class="pill ${followed?'active':''}" href="${href('following')}">${bi('我的關注','Following')} (${state.follows.length})</a></div><div class="filters"><label class="sr-only" for="people-q">${t('search')}</label><input id="people-q" name="q" data-filter="q" placeholder="${t('search')}" value="${esc(f.q)}"><label class="sr-only" for="people-language">${t('language')}</label><select id="people-language" data-filter="language"><option value="all">${bi('所有內容語言','All content languages')}</option><option value="zh-Hant" ${f.language==='zh-Hant'?'selected':''}>繁體中文</option><option value="en" ${f.language==='en'?'selected':''}>English</option></select><label class="sr-only" for="people-sort">${bi('排序','Sort')}</label><select id="people-sort" data-filter="sort"><option value="editorial">${bi('編輯排序','Editorial order')}</option><option value="name" ${f.sort==='name'?'selected':''}>${bi('姓名排序','Name A–Z')}</option></select></div><div class="filter-pills">${['all','entrepreneur','contestant','creator','professional'].map(r=>button(t(r),'role-filter',`pill ${f.role===r?'active':''}`,`data-role="${r}" aria-pressed="${f.role===r}"`)).join('')}</div><p class="demo-note" style="margin-bottom:25px">${bi('找到','Found')} ${list.length} ${bi('位示意人物','illustrative profiles')}</p>${list.length?`<div class="people-grid">${list.map(personCard).join('')}</div>`:`<div class="empty"><h2>${bi('尚無符合的人物','No matching profiles')}</h2>${button(t('clear'),'clear-filter','btn outline')}</div>`}</div>`}
function ownPerson(){return{id:'own',name:state.draft.name||'Your name',role:state.draft.roles?.[0]||'entrepreneur',place:state.draft.location||bi('未設定所在地','Location not set'),img:2,lang:state.draft.mainlang,title:[state.draft.headline||bi('妳的下一個篇章','Your next chapter'),state.draft.headline||'Your next chapter'],bio:[state.draft.bioZh||bi('在工作台填寫妳的故事。','Add your story in the studio.'),state.draft.bioEn||state.draft.bioZh||'Add your story in the studio.'],tags:[],own:true}}
function personPage(){const p=route.id==='own'?ownPerson():people.find(p=>p.id===route.id);if(!p)return`<div class="wrap empty">${bi('找不到人物。','Profile not found.')}<a class="btn" href="${href('people')}">${t('people')}</a></div>`;const template=p.own?state.draft.template:p.role==='contestant'?'portfolio':p.role==='professional'?'service':'editorial';return`<div class="wrap profile-template-${template}"><div class="breadcrumb"><a href="${href('people')}">${t('people')}</a> / ${esc(p.name)}</div>${p.own?`<div class="notice">${bi('草稿預覽：只有本機測試狀態，並非正式公開專頁。','Draft preview: browser-local state, not a live public profile.')} <a href="${href('studio','','profile')}">${t('edit')} ↗</a></div>`:''}<div class="profile-hero"><div class="portrait">${image(p.img)}</div><div class="profile-intro"><span class="eyebrow">HER ${template==='portfolio'?'PORTFOLIO':template==='service'?'EXPERTISE':'STORY'} / ${t(p.role)}</span><h1>${esc(p.name)}</h1><h2>${esc(bi(...p.title))}</h2><div class="profile-facts"><span>↗ ${esc(p.place)}</span><span>${p.lang==='en'?'English':'繁體中文'}</span><span>${t('verification')}</span></div><p>${esc(bi(...p.bio))}</p>${p.lang==='zh-Hant'&&state.lang==='en'?`<span class="badge">${bi('英文為示範翻譯','English sample translation')}</span>`:''}${p.own&&state.lang==='en'&&!state.draft.bioEn&&state.draft.bioZh?`<span class="badge">Original text · English translation unavailable</span>`:''}<div class="hero-actions">${button(`${state.follows.includes(p.id)?'✓':'+'} ${state.follows.includes(p.id)?t('following'):t('follow')}`,'follow','btn',`data-id="${p.id}" aria-pressed="${state.follows.includes(p.id)}"`)}${button(t('contact')+' ↗','invite','btn outline',`data-id="${p.id}"`)}</div><p class="demo-note">${p.own?t('local'):t('demo')}</p></div></div><div class="profile-tabs">${['story','gallery','contact'].map(k=>`<a class="pill" href="#${new URLSearchParams({page:'person',id:p.id,section:k})}">${k==='story'?bi('關於她','Her story'):k==='gallery'?t('gallery'):t('contact')}</a>`).join('')}${button(state.bookmarks.includes(p.id)?t('saved'):t('bookmark'),'bookmark','pill',`data-id="${p.id}" aria-pressed="${state.bookmarks.includes(p.id)}"`)}${button(t('share'),'share','pill',`data-id="${p.id}"`)}${button(t('report'),'report','pill',`data-id="${p.id}"`)}</div><div class="profile-body"><aside><div class="panel"><span class="eyebrow">OPEN TO POSSIBILITIES</span><h3>${bi('讓好的合作發生','Let’s create something meaningful')}</h3><p>${bi('演講、拍攝、品牌內容與公益交流。透過站內表單提出邀請，保護私人聯絡資料。','Speaking, creative work, brand storytelling and advocacy. Send a request through the platform, without exposing private contact details.')}</p><div style="margin-top:22px">${button(t('contact')+' ↗','invite','btn full',`data-id="${p.id}"`)}</div></div><p class="demo-note">${bi('徽章示意：本人自述不代表平台查核或賽事認證。','Badge note: self-reported information is not platform verification or pageant certification.')}</p></aside><div><section class="module" id="story" ${p.own&&!state.draft.modules.includes('story')?'hidden':''}><span class="eyebrow">01 / HER STORY</span><h2>${bi('用自己的步調，定義自己。','In her own words. On her own terms.')}</h2><p>${esc(bi(...p.bio))}</p></section><section class="module" id="gallery" ${p.own&&!state.draft.modules.includes('gallery')?'hidden':''}><span class="eyebrow">02 / SELECTED WORK</span><h2>${t('gallery')}</h2><div class="people-grid" style="grid-template-columns:repeat(2,1fr)">${[p.img,(p.img+1)%6].map((n,i)=>`<button data-action="gallery" data-id="${n}" class="person-photo" aria-label="${bi('開啟作品示意','Open illustrative work')} ${i+1}">${image(n,'loading="lazy"')}</button>`).join('')}</div><p class="demo-note">${bi('圖片為版型示意，非人物真實作品。','Layout images only, not this person’s real work.')}</p></section>${p.role==='contestant'?`<section class="module"><span class="eyebrow">03 / PERSONAL ADVOCACY</span><h2>${bi('舞台與公益','Stage & purpose')}</h2><p>${bi('可由本人新增參賽經歷、才藝與公益主題。測試版不填造任何實際賽事、獎項或名次。','Members can add pageant experience, talents and causes. This prototype does not fabricate real contests, awards or placements.')}</p><span class="badge">${t('verification')}</span></section>`:''}<section class="module" id="contact" ${p.own&&!state.draft.modules.includes('contact')?'hidden':''}><span class="eyebrow">04 / CONNECTION</span><h2>${bi('下一次合作，從對話開始。','The next chapter starts with a conversation.')}</h2>${button(t('contact')+' ↗','invite','btn outline',`data-id="${p.id}"`)}</section></div></div></div>`}
function field(name,label,value='',type='text',extra=''){return`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function check(name,label,checked=false,required=false){return`<label class="check"><input type="checkbox" name="${name}" ${checked?'checked':''} ${required?'required':''}><span>${label}</span></label>`}
function joinPage(){let step=state.step;const r=state.reg;let content='';if(step===0)content=`<h1>${bi('妳的故事，從這裡開始。','Your next chapter starts here.')}</h1><p>${bi('建立測試帳號，體驗自己的國際專頁。','Create a demo account and explore your international profile.')}</p><form id="register-form">${field('name',t('name'),r.name,'text','required maxlength="80" autocomplete="off"')}${field('email',t('email'),r.email,'email','required placeholder="name@example.com" autocomplete="off"')}${check('adult',bi('我已年滿 18 歲。此版本僅模擬成人註冊。','I am 18 or older. This version models adult registration only.'),r.consents?.adult,true)}${check('terms',bi('我同意測試版使用說明，了解這不是正式會員註冊。','I accept the demo terms and understand this is not a live account.'),r.consents?.terms,true)}${check('marketing',bi('我願意接收 SHE 最新消息（選填，不會寄信）。','I would like SHE updates (optional; no email is sent).'),r.consents?.marketing)}<div class="form-error" role="alert"></div><button class="btn full" type="submit">${bi('建立測試帳號','Create demo account')} ↗</button></form><div class="divider">${bi('其他登入方式','Other sign-in options')}</div><div class="providers">${button(bi('己美會員登入','SELF member sign-in'),'provider','', 'data-provider="SELF"')}${button(bi('LINE 快速登入','Continue with LINE'),'provider','', 'data-provider="LINE"')}</div><p class="demo-note">${bi('上述登入尚未串接；Email 測試流程可獨立完成。','Providers are not connected. The demo email flow works independently.')}</p>`;
if(step===1)content=`<h1>${bi('驗證信箱・流程模擬','Email verification · Simulation')}</h1><p>${bi('本測試不寄送 Email。請輸入下方公開測試碼，體驗驗證狀態。','No email is sent. Enter the displayed demo code to explore the verification state.')}</p><div class="notice">${bi('公開測試碼','Public demo code')}: <strong>246810</strong><br>${esc(r.email)}</div><form id="verify-form">${field('code',bi('六位數測試碼','Six-digit demo code'),'','text','required inputmode="numeric" maxlength="6" pattern="[0-9]{6}" autocomplete="off"')}<div class="form-error" role="alert"></div><div class="form-actions">${button(t('back'),'reg-back','btn outline')}<button class="btn" type="submit">${bi('確認測試碼','Confirm demo code')}</button></div></form><p class="demo-note">${bi('此碼僅用於展示，不提供帳號安全或所有權驗證。','This code demonstrates the interface only. It does not establish identity or secure an account.')}</p>`;
if(step===2)content=`<h1>${bi('妳有不只一種可能。','More than one way to be you.')}</h1><p>${bi('身分可複選，之後也能調整。','Choose all that describe you. You can change these later.')}</p><form id="roles-form">${['entrepreneur','contestant','creator','professional'].map(k=>check(k,t(k),r.roles.includes(k))).join('')}<div class="notice">${bi('選擇「佳麗」不會建立賽事報名或任何官方認證。','Selecting pageant talent does not register you for a contest or certify any credentials.')}</div><div class="form-error" role="alert"></div><div class="form-actions">${button(t('back'),'reg-back','btn outline')}<button class="btn" type="submit">${t('next')} ↗</button></div></form>`;
if(step===3)content=`<h1>${bi('為妳的故事，選一種版面。','Choose a home for your story.')}</h1><p>${bi('切換版型不會刪除資料。填寫內容後，妳可以決定何時送審。','Your content stays with you when you change layouts. Decide when you are ready for review.')}</p><form id="template-form"><label class="field">${bi('專頁版型','Profile template')}<select name="template">${['editorial','portfolio','service'].map(k=>`<option value="${k}" ${state.draft.template===k?'selected':''}>${t(k)}</option>`).join('')}</select></label>${field('location',t('location'),state.draft.location,'text','placeholder="Taipei / Paris / Bangkok" maxlength="80"')}<label class="field">${t('mainlang')}<select name="mainlang"><option value="zh-Hant" ${state.lang==='zh-Hant'?'selected':''}>繁體中文</option><option value="en" ${state.lang==='en'?'selected':''}>English</option></select></label><div class="form-actions">${button(t('back'),'reg-back','btn outline')}<button class="btn" type="submit">${bi('進入我的工作台','Enter my studio')} ↗</button></div></form>`;
return`<div class="wrap"><div class="auth-layout"><div class="auth-art">${image(1)}<div class="copy"><span class="eyebrow" style="color:#e2cfb5">SHE / YOUR NEXT CHAPTER</span><h2>Her story.<br><em>Her world.</em></h2><p>${bi('每一位她，都值得擁有自己的舞台。','Every woman deserves a place for her story.')}</p></div></div><div class="auth-form"><div class="steps" aria-label="${bi('註冊進度','Registration progress')}: ${step+1}/4">${[0,1,2,3].map(i=>`<span class="${i<=step?'done':''}"></span>`).join('')}</div>${content}<div class="notice">${t('local')}</div></div></div></div>`}
function sidebar(){const items=[['overview',t('overview')],['profile',t('profile')],['content',t('content')],['invitations',t('invitations')],['settings',t('settings')],['admin',t('admin')]];return`<aside class="sidebar"><span class="eyebrow">YOUR SHE STUDIO</span>${items.map(([k,label])=>`<a class="${route.tab===k?'active':''}" href="${href('studio','',k)}">${label}</a>`).join('')}<a href="${href('person','own')}">${t('previewpage')} ↗</a><a href="${href('guide')}">${t('guide')}</a><div class="notice">${bi('本機模擬工作台，非正式管理後台。','Browser-local sandbox, not a live administration system.')}</div></aside>`}
function studio(){if(!state.session)return`<div class="wrap">${heading('YOUR SHE STUDIO',bi('開始妳的個人篇章。','A place for your next chapter.'),bi('從原版動態雜誌進入註冊模擬，或直接載入示範會員。所有資料都與正式網站隔離。','Explore the demo registration or load a sample member. Everything is isolated from the live website.'))}<div class="panel"><div class="hero-actions"><a class="btn" href="${href('join')}">${bi('體驗註冊流程','Try registration')} ↗</a>${button(bi('載入示範會員','Load demo member'),'demo-login','btn outline')}</div><p class="demo-note">${t('local')}</p></div></div>`;let content='';switch(route.tab){case'profile':content=profileEditor();break;case'content':content=contentEditor();break;case'invitations':content=invitationsPage();break;case'settings':content=settingsPage();break;case'admin':content=adminPage();break;default:content=overviewPage()}
return`<div class="wrap"><div class="layout">${sidebar()}<div>${content}</div></div></div>`}
function workspaceHeading(title,desc,action=''){return`<div class="workspace-head"><div><span class="eyebrow">SHE STUDIO / ${bi('流程測試','WORKFLOW DEMO')}</span><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function overviewPage(){return`${workspaceHeading(bi('歡迎，','Welcome, ')+esc(state.draft.name),bi('每一個更新，都讓世界更認識妳。','Every update adds another dimension to your story.'),`<span class="badge ${state.status==='published'?'green':'wine'}">${t(state.status)}</span>`)}<div class="notice">${bi('以下數字為版型示範，並非真實成效。','The figures below illustrate the layout, not actual performance.')}</div><div class="stats">${[[1280,bi('專頁瀏覽（示意）','Profile views (sample)')],[state.follows.length,bi('本機追蹤人物','Locally followed')],[state.bookmarks.length,bi('本機收藏','Local saves')],[state.invitations.length,bi('測試合作邀請','Demo invitations')]].map(([n,l])=>`<div class="stat"><strong>${n.toLocaleString(state.lang)}</strong><span>${l}</span></div>`).join('')}</div><div class="spec-grid"><div class="panel"><span class="eyebrow">YOUR PROFILE</span><h2>${bi('準備好下一個篇章了嗎？','Ready for your next chapter?')}</h2><p>${bi('補齊個人介紹、挑選專頁版型，先預覽再送交審核。','Add your story, choose a layout, and preview it before submitting for review.')}</p><div class="hero-actions"><a class="btn" href="${href('studio','','profile')}">${t('profile')} ↗</a><a class="textlink" href="${href('person','own')}">${t('previewpage')} ↗</a></div></div><div class="panel"><span class="eyebrow">CONNECTIONS</span><h2>${t('invitations')}</h2><p>${bi('用合作表單管理需求，不必公開私人電話與 Email。','Manage opportunities without publishing your private phone number or email.')}</p><div style="margin-top:22px">${button(bi('加入一筆示範邀請','Add sample invitation'),'seed-invite','btn outline')}</div></div></div><section class="module"><h2>${bi('最近的測試紀錄','Recent demo activity')}</h2>${state.audit.length?`<div class="table-wrap"><table><thead><tr><th>${bi('操作','Action')}</th><th>${bi('時間','Time')}</th></tr></thead><tbody>${state.audit.slice(0,6).map(a=>`<tr><td>${esc(a.action[state.lang==='en'?1:0])}</td><td>${new Date(a.time).toLocaleString(state.lang,{timeZone:state.draft.timezone||'Asia/Taipei'})}</td></tr>`).join('')}</tbody></table></div>`:`<p>${bi('完成編輯或送審後，會在此記錄。','Your edits and review actions will appear here.')}</p>`}</section>`}
function profileEditor(){const d=state.draft;return`${workspaceHeading(t('profile'),bi('三種版型，共用一份內容。草稿與已發布版本分開保存。','Three layouts, one content model. Drafts and published snapshots stay separate.'),`<span class="badge wine">${t(state.status)}</span>`)}<form id="profile-form"><div class="editor-grid"><div class="panel">${field('name',t('name'),d.name,'text','required maxlength="80"')}${field('original',t('original'),d.original,'text','maxlength="100"')}${field('slug',t('url'),d.slug,'text','required pattern="[a-z0-9]+(?:-[a-z0-9]+)*" maxlength="50"')}<small>/${state.lang==='en'?'en':'zh-hant'}/people/${esc(d.slug||'my-story')}</small>${field('headline',t('headline'),d.headline,'text','maxlength="150"')}${field('location',t('location'),d.location,'text','maxlength="80"')}<label class="field">${bi('繁體中文介紹','Biography · Traditional Chinese')}<textarea name="bioZh" maxlength="3000">${esc(d.bioZh)}</textarea></label><label class="field">${bi('英文介紹','Biography · English')}<textarea name="bioEn" maxlength="3000">${esc(d.bioEn)}</textarea><small>${bi('未填英文時，英文頁顯示原文並標示缺少翻譯。','If empty, the English page shows the original text with a translation notice.')}</small></label><fieldset style="border:1px solid var(--line);margin:20px 0"><legend>${t('role')}</legend>${['entrepreneur','contestant','creator','professional'].map(k=>check(k,t(k),d.roles.includes(k))).join('')}</fieldset><label class="field">${t('mainlang')}<select name="mainlang"><option value="zh-Hant" ${d.mainlang==='zh-Hant'?'selected':''}>繁體中文</option><option value="en" ${d.mainlang==='en'?'selected':''}>English</option></select></label><label class="field">${bi('專頁版型','Profile template')}<select name="template">${['editorial','portfolio','service'].map(k=>`<option value="${k}" ${d.template===k?'selected':''}>${t(k)}</option>`).join('')}</select></label><fieldset style="border:1px solid var(--line)"><legend>${bi('顯示模組','Visible modules')}</legend>${['story','gallery','contact'].map(k=>check('module-'+k,k==='story'?bi('品牌故事','Personal story'):t(k),d.modules.includes(k))).join('')}</fieldset>${check('photo',bi('我了解正式照片上傳需提供使用授權（模擬確認）。','I understand that live uploads require image rights (demo acknowledgement).'),d.photoConsent)}${check('publicConsent',bi('我選擇在審核通過後公開專頁（模擬）。','I choose to make my profile public after approval (simulation).'),d.publicConsent)}<div class="form-error" role="alert"></div><div class="form-actions"><button class="btn outline" type="submit">${t('save')}</button>${button(t('submit')+' ↗','submit-review','btn')}</div></div><aside><div class="editor-preview">${image(2)}<h3 id="live-preview-name">${esc(d.name)}</h3><span class="badge">${t(d.template)}</span><p id="live-preview-headline">${esc(d.headline)||bi('在這裡，看見自己的下一個篇章。','A new chapter, in your own words.')}</p><div style="margin-top:22px"><a class="textlink" data-action="preview-own" href="${href('person','own')}">${t('previewpage')} ↗</a></div></div><div class="notice">${bi('圖片使用既有官網形象示意素材。此版不將上傳檔案送往任何伺服器。','Uses illustrative imagery from the existing site. This version does not upload files to a server.')}</div><label class="field">${bi('選取圖片以測試本機預覽','Choose an image for a local preview')}<input type="file" id="local-image" accept="image/jpeg,image/png,image/webp"><small>${bi('限 JPG、PNG 或 WebP，最大 5MB；重新整理後清除。','JPG, PNG or WebP; max 5 MB. Cleared on reload.')}</small></label></aside></div></form>`}
function contentEditor(){return`${workspaceHeading(t('content'),bi('草稿、排程與發布狀態的本機模擬。','Browser-local draft, scheduling and publishing states.'))}<div class="panel"><form id="post-form">${field('title',bi('動態標題','Update title'),'','text','required maxlength="150"')}<label class="field">${bi('內容','Content')}<textarea name="body" required maxlength="3000"></textarea></label><div class="field-row"><label class="field">${t('language')}<select name="language"><option value="zh-Hant">繁體中文</option><option value="en">English</option></select></label><label class="field">${bi('本機排程時間（選填）','Local schedule time (optional)')}<input type="datetime-local" name="schedule"><small>${bi('使用目前裝置時區；未啟用背景發布。','Uses your device time zone; background publication is not enabled.')}</small></label></div><div class="form-actions"><button class="btn" type="submit">${bi('儲存動態','Save update')}</button></div></form></div><div class="stack" style="margin-top:25px">${state.posts.length?state.posts.map((p,i)=>`<article class="request"><span class="badge">${p.schedule?bi('已排程・模擬','Scheduled · simulated'):t(p.status)}</span><h3>${esc(p.title)}</h3><p>${esc(p.body)}</p><small>${esc(p.language)}${p.schedule?' · '+esc(p.schedule):''}</small><div class="actions">${button(bi('切換發布狀態','Toggle publication'),'post-status','',`data-id="${i}"`)}</div></article>`).join(''):`<div class="empty">${bi('尚無動態，試著建立第一則內容。','No updates yet. Create your first one above.')}</div>`}</div>`}
function invitationsPage(){return`${workspaceHeading(t('invitations'),bi('所有合作內容均為測試資料，不會通知或傳送給他人。','All opportunities are sample data. No messages are sent to anyone.'),button(bi('加入示範邀請','Add sample'),'seed-invite','btn outline'))}<div class="stack">${state.invitations.length?state.invitations.map((r,i)=>`<article class="request"><span class="badge ${r.status==='accepted'?'green':'wine'}">${t(r.status)}</span><h3>${esc(r.name)} · ${esc(r.type)}</h3><p>${esc(r.detail)}</p><p>${bi('預算','Budget')}: ${esc(r.budget||bi('待討論','To discuss'))} · ${bi('地點','Location')}: ${esc(r.location||'—')}</p><p>${bi('時間','Time')}: ${esc(r.date||'—')} ${esc(r.timezone||'')}</p><small>${bi('送往','For')}: ${esc(r.target||state.draft.name)}</small><div class="actions">${['accept','decline','more','block'].map(a=>button(t(a),'invitation-action','',`data-id="${i}" data-value="${a}"`)).join('')}${button(t('report'),'report','',`data-id="invitation-${i}"`)}</div></article>`).join(''):`<div class="empty"><h2>${bi('新的合作，正在路上。','Your next connection starts here.')}</h2><p>${bi('可以從人物頁送出測試邀請，或加入一筆示範資料。','Send a demo request from a profile, or add a sample invitation.')}</p></div>`}</div>`}
function settingsPage(){return`${workspaceHeading(t('settings'),bi('偏好設定可本機儲存；安全相關功能僅展示規劃。','Preferences save locally. Security actions demonstrate the proposed interface.'))}<form id="settings-form"><div class="panel"><h2>${bi('國際資料設定','International settings')}</h2>${field('nationality',t('country'),state.draft.nationality,'text','maxlength="80"')}${field('residence',t('residence'),state.draft.residence||'','text','maxlength="80"')}<label class="field">${t('timezone')}<select name="timezone">${['Asia/Taipei','Asia/Tokyo','Asia/Bangkok','Asia/Singapore','Europe/Paris','Europe/London','America/New_York','America/Mexico_City','UTC'].map(z=>`<option ${state.draft.timezone===z?'selected':''}>${z}</option>`).join('')}</select></label>${field('phone',t('phone'),state.draft.phone||'','tel','placeholder="+33 6 00 00 00 00" maxlength="30"')}${check('marketing',bi('接收最新消息（模擬，不會寄信）','Receive updates (simulated; no emails)'),state.reg.consents?.marketing)}<button class="btn" type="submit">${bi('儲存設定','Save preferences')}</button></div></form><div class="panel" style="margin-top:25px"><h2>${bi('登入與安全','Sign-in & security')}</h2><p>${bi('Email 驗證、帳號復原、換信箱、登出其他裝置及多因素驗證需正式身分服務支援。測試版不蒐集密碼，也不提供真實安全驗證。','Email verification, recovery, email changes, device sessions and MFA require a live identity service. This prototype collects no passwords and provides no actual authentication.')}</p><div class="form-actions">${button(bi('檢視帳號復原流程','View recovery flow'),'recovery','btn outline')}${button(bi('下載本機測試資料','Export local demo data'),'export','btn outline')}${button(t('logout'),'logout','btn outline')}</div></div><div class="panel" style="margin-top:25px"><h2>${bi('資料控制','Data control')}</h2><p>${t('local')}</p><div class="form-actions">${button(bi('模擬停用專頁','Simulate deactivation'),'withdraw','btn outline')}${button(bi('刪除本機測試帳號','Delete local demo account'),'delete-account','btn outline')}</div></div>`}
function adminPage(){return`${workspaceHeading(t('admin'),bi('測試角色切換僅供流程確認，沒有正式權限控制。','Role simulation for review only. No production authorization is enforced.'))}<div class="notice">${bi('這是刻意開放的審核沙盒，不可直接用作正式後台；真實後台須由伺服器檢查角色及權限。','This is an intentionally open review sandbox. Live administration must enforce roles and permissions on the server.')}</div><div class="panel"><h2>${esc(state.draft.name)}</h2><span class="badge wine">${t(state.status)}</span><p style="margin-top:15px">${bi('審核語言、公開同意、人物介紹與素材授權。正式流程需記錄審核者及變更版本。','Review language, publication consent, biography and media rights. A live workflow must record reviewers and content versions.')}</p><div class="form-actions"><a class="btn outline" href="${href('person','own')}">${t('previewpage')}</a>${button(bi('核准模擬發布','Approve demo publication'),'approve','btn',state.status!=='review'?'disabled':'')}${button(bi('退回修改','Request changes'),'request-changes','btn outline',state.status!=='review'?'disabled':'')}${button(bi('撤下專頁','Withdraw profile'),'withdraw','btn outline')}</div>${state.reviewReason?`<div class="notice">${esc(state.reviewReason)}</div>`:''}</div><div class="panel" style="margin-top:25px"><h2>${bi('版本狀態','Version state')}</h2><p>${bi('最近一次核准版本','Last approved snapshot')}: ${esc(state.publishedProfile?.name||bi('尚無','None'))}</p><p>${bi('目前編輯中的草稿','Current draft')}: ${esc(state.draft.name)}</p><p>${bi('修改草稿不會更動此已核准快照。','Draft edits do not overwrite the approved snapshot.')}</p></div>`}
function journal(){return`<div class="wrap">${heading('THE JOURNAL',bi('關於她，也關於世界。','Women. Perspectives. Possibility.'),bi('所有文章為測試編輯內容，不代表真實採訪。','All stories are editorial samples, not real interviews.'))}<div class="story-grid">${storyTitles.map((s,i)=>`<article class="story">${image(i,'loading="lazy" style="height:300px;object-position:center 20%"')}<span class="eyebrow" style="margin-top:18px">SHE EDITORIAL / ${bi('示範文章','EXAMPLE STORY')}</span><a href="${href('article',String(i))}"><h3>${bi(...s)}</h3></a><footer>2026.10.24 · SHE EDITORIAL</footer></article>`).join('')}</div></div>`}
function article(){const i=Math.min(2,Math.max(0,Number(route.id)||0));return`<article class="article wrap"><span class="eyebrow">SHE EDITORIAL / ${bi('示範文章','EXAMPLE STORY')}</span><h1>${bi(...storyTitles[i])}</h1><p class="demo-note">2026.10.24 · SHE EDITORIAL · ${bi('非真實採訪','NOT A REAL INTERVIEW')}</p><p class="lead">${bi('每一個故事，都值得用自己的語言被理解。每一段經歷，都可能開啟新的合作。','Every story deserves to be understood in its own voice. Every experience can become the beginning of a new connection.')}</p>${image(i)}<h2>${bi('從認識自己，到被世界看見','From knowing yourself to being seen')}</h2><p>${bi('SHE 的人物誌將故事、作品與專業放在一起。閱讀者可以了解一個人的觀點，也能找到進一步交流的方式。這段文字用來展示長文閱讀、文字層次與中英文切換。','SHE brings personal stories, creative work and expertise together. Readers can discover a perspective and find a thoughtful way to connect. This sample demonstrates long-form typography, hierarchy and language switching.')}</p><blockquote style="font-family:var(--serif);font-size:35px;border-left:2px solid var(--gold);padding-left:25px">${bi('每一位她，都有自己的世界。','Her story. Her world.')}</blockquote><p>${bi('正式內容需有作者、來源、授權及發布日期；付費合作與編輯內容將清楚區分。測試內容不會自動出現在正式網站。','Live stories will carry authorship, sources, rights and publication dates. Paid partnerships will be distinguished from editorial work. Demo content does not publish to the live website.')}</p><a class="textlink" href="${href('journal')}">← ${t('journal')}</a></article>`}
function guide(){return`<div class="wrap">${heading('A PRIVATE FIRST LOOK',bi('歡迎試用，新一章的 SHE。','Welcome to the next chapter of SHE.'),bi('這個獨立測試站用來確認版面、文案與操作流程。正式 she.self.com.tw 未被修改。','An isolated prototype for reviewing design, copy and flows. The live she.self.com.tw website is unchanged.'))}<div class="spec-grid">${[[bi('01 探索雙語首頁','01 Explore both languages'),bi('切換繁中／EN，再進入人物、文章及短影音；頁面位置與未送出的主要表單會保留。','Switch 繁中 / EN across profiles, stories and video concepts. The route and primary unsent form values are preserved.'),'home'],[bi('02 體驗國際註冊','02 Try international registration'),bi('使用虛構 Email，輸入畫面提供的測試碼，複選身分，再選擇版型。','Use a fictional email, enter the visible demo code, select roles and choose a template.'),'join'],[bi('03 經營專頁與合作','03 Manage a profile and opportunities'),bi('載入示範會員，編輯中英文、儲存草稿、預覽、送審與處理合作邀請。','Load a sample member, edit bilingual content, save, preview, submit and manage invitations.'),'studio'],[bi('04 查看系統規格','04 Review the blueprint'),bi('查看權限、資料關係、開發階段與上線前驗收。','Review permissions, data relationships, delivery phases and production acceptance.'),'spec']].map(([title,body,page])=>`<div class="panel"><h2>${title}</h2><p>${body}</p><a class="textlink" style="margin-top:20px" href="${href(page)}">${bi('開始測試','Explore')} ↗</a></div>`).join('')}</div><div class="notice">${bi('可操作：本機註冊模擬、專頁草稿、三種版型、搜尋、追蹤收藏、合作邀請、送審與審核。','Interactive: local demo registration, profile drafts, three templates, search, following, saves, invitations and review states.')}</div><div class="notice">${bi('待串接：真實驗證信、己美／LINE 登入、跨裝置資料庫、檔案儲存、影片、正式權限、通知與付款。短影音目前為有字幕的圖片動態示意，沒有真人訪談影片。','Not connected: real verification email, SELF / LINE sign-in, cross-device storage, uploads, video, production permissions, notifications or payments. Video cards open captioned motion-image concepts, not real interviews.')}</div><div class="form-actions">${button(t('reset'),'reset','btn outline')}<a class="btn outline" href="/blueprint.md" download>${t('download')} ↗</a></div></div>`}
function spec(){const sections=[
['01 / POSITIONING',bi('獨立國際女性平台','An independent international women’s platform'),bi('SHE 服務企業家、佳麗、創作者與專業人士。FOBI 佳麗如同其他會員自行加入；本案沒有賽事管理、名單同步或官方賽事徽章。','SHE serves entrepreneurs, pageant talent, creators and professionals. FOBI participants may join independently, just like other members. No contest management, roster synchronization or official contest badges.')],
['02 / ARCHITECTURE',bi('漸進擴充既有網站','Extend the current site progressively'),bi('已讀取的公開前端顯示 SHE 具有 React 模組、雜誌介面、個人專頁及外部資料呼叫。未取得原始碼儲存庫、正式會員及後台存取，無法確認部署與權限。先保留既有路由及商品入口，盤點後再決定整合方式。','Public assets show a React-based magazine interface, personal pages and external data requests. Repository, live member services and admin access have not been inspected. Preserve existing routes and catalog entry points; decide integration after a source audit.')],
['03 / INTERNATIONALIZATION',bi('介面與內容分層翻譯','Separate interface and content translation'),bi('首階段 zh-Hant / en。穩定翻譯鍵、原文與譯文版本、翻譯審核狀態。正式站採語系網址、hreflang、canonical、語系 sitemap 與分享預覽。測試站使用 hash 路由且 noindex，不能作為正式 SEO 實作。','Launch with zh-Hant / en. Use stable interface keys, source and translated content versions, and review status. Production needs locale paths, hreflang, canonicals, sitemaps and social metadata. This noindex prototype uses hash routing and is not a production SEO implementation.')],
['04 / IDENTITY',bi('帳號、人物與授權分開','Separate accounts, profiles and authorization'),bi('帳號 → 登入身分；帳號 → 人物專頁；專頁 → 模組、翻譯、內容與合作邀請。一人可複選人物身分。協作者透過明確授權加入，不以姓名或未驗證 Email 合併帳號。','Account → sign-in identities; account → person profile; profile → modules, translations, content and invitations. Multiple roles per person. Delegates require explicit grants; never merge using names or unverified emails.')],
['05 / REVIEW',bi('草稿與發布版本分開','Drafts and published versions'),bi('草稿 → 送審 → 需修改／發布 → 撤下。重大資料更新重新審核，一般內容按風險分類。審核與翻譯版本需有操作者、原因、時間與版本號。','Draft → review → changes requested / published → withdrawn. Re-review material profile changes; use risk-based review for routine posts. Record actor, reason, time and version for review and translations.')],
['06 / ACCESS',bi('正式權限矩陣','Production permission matrix'),bi('會員僅編輯自己的專頁；協作者按授權模組操作；編輯審核內容；翻譯者處理指定語言；客服處理申訴；管理者管理角色。所有權限由伺服器與資料層執行，敏感角色使用 MFA。測試版沒有這項安全能力。','Members edit their own profiles; delegates edit granted modules; editors review content; translators access assigned languages; support handles reports; administrators assign roles. Enforce access on the server and data layer, with MFA for sensitive roles. This prototype does not implement these controls.')],
['07 / DATA & RIGHTS',bi('隱私、素材與生命週期','Privacy, media rights and lifecycle'),bi('私人聯絡資料與公開資料隔離；證件不得出現在公開 API。素材記錄授權、擁有者、字幕與替代文字。定義資料保留、匯出、刪除、備份及復原；期限依實際營運與法律需求確認。','Separate private contact data from public profiles; never expose documents through public APIs. Record media owner, rights, captions and alt text. Define retention, export, deletion, backups and restore procedures based on actual operations and legal review.')],
['08 / BUSINESS',bi('經營價值與付費界線','Business value and clear paid boundaries'),bi('基本閱讀與專頁先行；後續評估進階經營工具、影音製作、品牌專題及活動。付費方案不能代表身分查核或影響編輯公信力。價格與配額待需求驗證，不設定虛構營收。','Start with reading and basic profiles; evaluate premium tools, production services, brand features and events. Paid plans do not imply verification or editorial endorsement. Validate pricing and limits before forecasting revenue.')],
['09 / DELIVERY',bi('分期與依賴','Delivery phases and dependencies'),bi('第一階段：中英文、Email 身分服務、人物頁、工作台、合作邀請與必要審核。第二階段：影音、追蹤內容、排程與協作者。第三階段：更多語言及人工監督的 AI 協作。依賴產品設計、前後端、編輯翻譯、QA 及維運資源；盤點後估工期與成本。','Phase 1: bilingual UI, email identity, profiles, studio, invitations and review. Phase 2: video, following feed, schedules and delegates. Phase 3: more languages and supervised AI assistance. Requires product design, frontend/backend, editorial translation, QA and operations. Estimate cost and timing after the audit.')],
['10 / RELEASE',bi('正式上線與回復條件','Production release and rollback'),bi('保留舊路由或設轉址；先在隔離環境驗證資料遷移、登入、權限及通知。準備資料快照、前版部署與回復演練，經業主確認後才覆蓋正式站。本次測試不取得正式寫入權限。','Preserve or redirect legacy routes. Verify migration, sign-in, permissions and notifications in staging. Prepare snapshots, previous deployments and a rollback rehearsal. Replace production only after the owner confirms. This preview has no live write access.')]
];return`<div class="wrap">${heading('PRODUCT & SYSTEM BLUEPRINT',t('spec'),bi('可操作原型搭配正式開發規格，清楚區分示意與待實作範圍。','An interactive prototype accompanied by an explicit production blueprint.'))}<div class="form-actions"><a class="btn" href="/blueprint.md" download>${t('download')} ↗</a><a class="textlink" href="/acceptance.md" download>${bi('下載驗收清單','Download acceptance checklist')} ↗</a><a class="textlink" href="/interface-copy.json" download>${bi('下載雙語文案','Download bilingual UI copy')} ↗</a></div><div style="margin-top:30px">${sections.map(([ey,title,body])=>`<details ${ey.startsWith('01')?'open':''}><summary>${ey} · ${title}</summary><p style="padding:10px 0 20px">${body}</p></details>`).join('')}</div><div class="notice">${bi('正式驗收：非台灣註冊、中英文完整流程、長姓名、翻譯回退、手機、鍵盤、越權測試、私人 API、帳號刪除、還原及既有路由。此原型不能取代安全、資料遷移與無障礙驗收。','Production acceptance includes international registration, bilingual flows, long names, fallback, mobile, keyboard use, authorization tests, private APIs, deletion, restore and legacy routes. This prototype does not replace security, migration or accessibility verification.')}</div></div>`}
function privacy(){return`<div class="wrap">${heading('PRIVACY / PROTOTYPE',t('privacy'))}<div class="panel"><p>${t('local')}</p><p style="margin-top:18px">${bi('測試資料包含妳輸入的示範名稱、內容、偏好及邀請，保存在 localStorage。它不會被送到 SHE、FOBI、Email 或社群服務。此預覽站的存取由託管服務管理；頁面會載入 Google Fonts 字體。','Demo names, content, preferences and invitations are stored in localStorage. They are not sent to SHE, FOBI, email or social services. Hosting controls access to this preview. The page loads fonts from Google Fonts.')}</p><p style="margin-top:18px">${bi('此說明僅適用測試版，不是正式平台的法律條款或全球合規聲明。正式條款需依營運地區、服務內容及資料處理方式另行制定。','This notice applies to the prototype only. It is not the production terms or a claim of global compliance. Production terms require review for actual regions, services and data processing.')}</p><div class="form-actions">${button(t('reset'),'reset','btn outline')}</div></div></div>`}
function render(){document.documentElement.lang=state.lang;document.body.classList.toggle('motion-off',state.motion);document.title=`SHE — ${route.page==='home'?bi('她的故事，世界的下一頁','Her story. Her world.'):t(({studio:'workspace',person:'profile',article:'journal',following:'following'})[route.page]||route.page)} · ${bi('測試版','Preview')}`;const pages={home,people:()=>discover(),following:()=>discover(true),person:personPage,join:joinPage,studio,journal,article,tv:()=>`<div class="wrap">${heading('SHE TV',bi('她，親自說。','In her own words.'),bi('以下為有字幕的圖片動態示意，非真人訪談影片。','Captioned motion-image concepts, not real interview videos.'))}<div class="video-grid">${[0,1,2].map(videoCard).join('')}</div></div>`,events:()=>`<div class="wrap">${heading('SHE CIRCLE',t('events'),bi('以交流，打開更多可能。所有活動為概念示意。','New possibilities through conversation. All gatherings are illustrative.'))}${eventRows()}</div>`,guide,spec,privacy};if(['home','people','journal','tv','events','following','person','shop','member'].includes(route.page)){document.body.classList.add('magazine-view');$('#app').innerHTML=`<div class="magazine-preview-bar">${bi('獨立測試版・保留原版動態雜誌','Independent preview · Original magazine experience')}<a href="${href('guide')}">${t('guide')} ↗</a><a href="/workspace/">${bi('正式會員入口','Member sign-in')} ↗</a></div><iframe id="magazine-frame" title="${bi('SHE React 動態雜誌','SHE React magazine')}" src="/magazine/index.html?v=2&${new URLSearchParams({lang:state.lang,page:route.page,id:route.id})}"></iframe>`;return}document.body.classList.remove('magazine-view');$('#app').innerHTML=header()+`<main id="main" tabindex="-1" class="reveal">${(pages[route.page]||home)()}</main>`+footer();if(heroPaused||state.motion)$('.hero-media>img')?.style.setProperty('animation-play-state','paused');const section=new URLSearchParams(location.hash.slice(1)).get('section');if(section)requestAnimationFrame(()=>$(`#${section}`)?.scrollIntoView({behavior:'auto'}));}
function captureForm(){const f=$('#profile-form');if(f){const d=new FormData(f);for(const k of ['name','original','slug','headline','location','bioZh','bioEn','mainlang','template'])state.draft[k]=String(d.get(k)||'');state.draft.roles=['entrepreneur','contestant','creator','professional'].filter(k=>d.has(k));state.draft.modules=['story','gallery','contact'].filter(k=>d.has('module-'+k));state.draft.publicConsent=d.has('publicConsent');state.draft.photoConsent=d.has('photo');}const r=$('#register-form');if(r){const d=new FormData(r);state.reg.name=String(d.get('name')||'');state.reg.email=String(d.get('email')||'');state.reg.consents={adult:d.has('adult'),terms:d.has('terms'),marketing:d.has('marketing')};}}
function preserveVisibleForms(){const forms=[...document.querySelectorAll('main form')].map(f=>({id:f.id,values:[...f.elements].filter(e=>e.name&&e.type!=='file').map(e=>({name:e.name,value:e.value,checked:e.checked,type:e.type}))}));return()=>{for(const f of forms){const el=document.getElementById(f.id);if(!el)continue;for(const item of f.values){const input=[...el.elements].find(x=>x.name===item.name);if(input){input.value=item.value;if(item.type==='checkbox'||item.type==='radio')input.checked=item.checked;}}}}}
function modal(html){modalLastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="modal-close" data-action="close-modal" aria-label="${t('close')}">×</button>${html}</section></div>`;document.body.style.overflow='hidden';requestAnimationFrame(()=>$('.modal input,.modal select,.modal textarea,.modal button')?.focus())}
function closeModal(){$('#modal-root').innerHTML='';document.body.style.overflow='';modalLastFocus?.focus?.()}
function invite(id){const p=id==='own'?ownPerson():people.find(p=>p.id===id)||people[0];modal(`<span class="eyebrow">A NEW CONNECTION</span><h2 id="modal-title">${t('contact')} · ${esc(p.name)}</h2><p>${bi('此表單只建立本機測試紀錄，不會寄信或聯絡此人物。請使用虛構資訊。','Creates a local demo record only. No email or contact is made. Use fictional information.')}</p><form id="invite-form" data-target="${esc(p.name)}">${field('name',bi('合作方／品牌名稱','Your name / brand'),'','text','required maxlength="100"')}${field('email',bi('測試聯絡 Email','Demo contact email'),'','email','required placeholder="brand@example.com"')}<label class="field">${bi('合作類型','Collaboration type')}<select name="type">${[bi('演講','Speaking'),bi('品牌內容','Brand content'),bi('拍攝','Creative production'),bi('公益活動','Advocacy'),bi('專業服務','Professional services'),bi('聯名合作','Brand collaboration')].map(s=>`<option>${s}</option>`).join('')}</select></label><label class="field">${bi('需求說明','Project details')}<textarea name="detail" required maxlength="2000"></textarea></label><div class="field-row">${field('budget',bi('預算區間與幣別','Budget range & currency'),'','text','placeholder="EUR 1,000–2,000" maxlength="80"')}${field('location',bi('地點／線上','Location / online'),'','text','maxlength="100"')}</div><div class="field-row">${field('date',bi('預計日期（選填）','Preferred date (optional)'),'','date')}<label class="field">${t('timezone')}<select name="timezone">${['UTC','Asia/Taipei','Asia/Tokyo','Europe/Paris','Europe/London','America/New_York'].map(s=>`<option>${s}</option>`).join('')}</select></label></div>${check('consent',bi('我了解這是模擬，不會傳送真實邀請。','I understand this is a simulation; no real invitation is sent.'),false,true)}<button class="btn full" type="submit">${t('send')} ↗</button></form>`)}
function seedInvite(){state.invitations.unshift({name:'Maison Studio (Demo)',type:bi('品牌內容合作','Brand storytelling'),detail:bi('邀請討論一場關於女性創意與個人品牌的示範對談。','A sample invitation for a conversation on women, creativity and personal branding.'),budget:'EUR 1,000–2,000 (Demo)',location:'Online',date:'',timezone:'UTC',status:'pending',target:state.draft.name});persist();toast(bi('已加入示範邀請。','Sample invitation added.'));render()}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;if(a==='lang'){captureForm();const restore=preserveVisibleForms(),y=window.scrollY;closeModal();state.lang=b.dataset.lang;persist();render();restore();window.scrollTo(0,y);return}if(a==='menu'){const n=$('.navlinks');n.classList.toggle('open');b.setAttribute('aria-expanded',n.classList.contains('open'));return}if(a==='close-modal'){closeModal();return}if(a==='motion'){state.motion=!state.motion;persist();document.body.classList.toggle('motion-off',state.motion);b.setAttribute('aria-pressed',state.motion);b.textContent=t('motion')+(state.motion?' ✓':' ○');return}
if(a.startsWith('hero-')){if(a==='hero-pause')heroPaused=!heroPaused;else heroIndex=(heroIndex+(a==='hero-prev'?-1:1)+people.length)%people.length;$('#hero-slot').innerHTML=hero();if(heroPaused||state.motion)$('.hero-media>img')?.style.setProperty('animation-play-state','paused');return}
if(a==='follow'||a==='bookmark'){const key=a==='follow'?'follows':'bookmarks';state[key]=state[key].includes(id)?state[key].filter(x=>x!==id):[...state[key],id];persist();const y=window.scrollY;render();window.scrollTo(0,y);return}
if(a==='share'){const u=location.origin+'/'+href('person',id);try{await navigator.clipboard.writeText(u);toast(bi('已複製測試專頁連結。','Demo profile link copied.'))}catch{modal(`<h2 id="modal-title">${t('share')}</h2><input readonly value="${esc(u)}" class="full">`)}return}
if(a==='role-filter'){state.filters.role=b.dataset.role;persist();render();return}if(a==='clear-filter'){state.filters={...defaults.filters};persist();render();return}if(a==='invite'){invite(id);return}if(a==='seed-invite'){seedInvite();return}
if(a==='video'){const p=people[Number(id)||0];modal(`<span class="eyebrow">SHE TV / MOTION CONCEPT</span><h2 id="modal-title">${esc(p.name)}</h2><div class="video-demo">${image(p.img)}<span class="caption">${bi(...p.title)}</span></div><div class="form-actions">${button(bi('暫停動態','Pause motion'),'video-pause','btn outline')}<span class="badge">${bi('字幕已顯示・無音訊','Captions shown · No audio')}</span></div><p>${bi('這是圖片動態與字幕示意；尚未串接真正的訪談影片。','A motion-image and caption concept. Real interview video is not connected.')}</p>`);return}
if(a==='video-pause'){const el=$('.video-demo');el.classList.toggle('paused');b.textContent=el.classList.contains('paused')?bi('播放動態','Resume motion'):bi('暫停動態','Pause motion');return}if(a==='gallery'){modal(`<h2 id="modal-title">${t('gallery')} / ${bi('形象示意','Illustrative')}</h2>${image(Number(id),'style="max-height:65vh;object-fit:contain"')}`);return}
if(a==='event'){modal(`<h2 id="modal-title">${bi('活動消息登記・模擬','Event updates · Simulation')}</h2><p>${bi('尚無真實活動日期、訂位或付款。本測試不會寄送通知。','No live dates, reservations or payments. This demo sends no notifications.')}</p><form id="event-form">${field('email',t('email'),'','email','required placeholder="name@example.com"')}${check('consent',bi('我同意模擬登記。','I agree to a demo registration.'),false,true)}<button type="submit" class="btn">${bi('完成測試','Complete demo')}</button></form>`);return}
if(a==='provider'){modal(`<h2 id="modal-title">${esc(b.dataset.provider)} · ${t('unconnected')}</h2><p>${bi('正式環境需先確認服務授權、回呼網址與帳號綁定。此測試不會開啟或模擬成功的第三方登入。','Production requires provider access, callback configuration and account linking. This demo does not perform third-party sign-in.')}</p><a class="btn" data-action="close-modal" href="${href('join')}">${bi('使用 Email 測試流程','Use the email demo flow')}</a>`);return}
if(a==='reg-back'){captureForm();state.step=Math.max(0,state.step-1);persist();render();return}
if(a==='demo-login'){state.session=true;state.draft={...state.draft,name:'Alex Morgan',headline:bi('創意・品牌・跨文化合作','Creative strategy · Brands · Culture'),bioZh:'用自己的步調，將故事與專業連結世界。這是示範會員介紹。',bioEn:'Connecting stories, expertise and cultures. This is a demo member biography.',location:'Paris / Taipei'};audit(['載入示範會員','Loaded demo member']);persist();go('studio');return}
if(a==='submit-review'){const f=$('#profile-form');if(!f.reportValidity())return;captureForm();if(!state.draft.roles.length||!state.draft.publicConsent||!state.draft.photoConsent||(!state.draft.bioZh.trim()&&!state.draft.bioEn.trim())){toast(bi('請填寫介紹、選擇身分，並確認照片授權與公開同意。','Add a biography, select a role, and confirm media rights and publication consent.'));return}state.status='review';audit(['專頁送交審核（模擬）','Profile submitted for review (demo)']);persist();toast(bi('已送審，可到「審核模擬」測試核准或退回。','Submitted. Use the review sandbox to approve or request changes.'));render();return}
if(a==='preview-own'){captureForm();persist();return}
if(a==='approve'){if(state.status!=='review')return;state.status='published';state.publishedProfile=structuredClone(state.draft);audit(['核准模擬發布','Approved demo publication']);persist();render();toast(bi('本機模擬發布完成，沒有變更正式網站。','Demo publication saved locally. The live site is unchanged.'));return}
if(a==='request-changes'){modal(`<h2 id="modal-title">${bi('退回修改','Request changes')}</h2><form id="review-form"><label class="field">${bi('修改原因','Reason')}<textarea name="reason" required maxlength="1000"></textarea></label><button type="submit" class="btn">${bi('確認退回','Confirm changes request')}</button></form>`);return}
if(a==='withdraw'){state.status='withdrawn';state.publishedProfile=null;audit(['撤下本機模擬專頁','Withdrew local demo profile']);persist();render();toast(bi('已撤下本機模擬專頁。','Local demo profile withdrawn.'));return}
if(a==='invitation-action'){const r=state.invitations[Number(id)];if(!r)return;r.status=({accept:'accepted',decline:'declined',more:'details',block:'blocked'})[b.dataset.value];audit(['更新合作邀請狀態','Updated invitation status']);persist();render();return}
if(a==='post-status'){const p=state.posts[Number(id)];if(!p)return;p.status=p.status==='published'?'draft':'published';p.schedule='';persist();render();return}
if(a==='report'){modal(`<h2 id="modal-title">${bi('檢舉內容・模擬','Report content · Simulation')}</h2><form id="report-form"><label class="field">${bi('檢舉原因','Reason')}<select name="reason"><option>${bi('冒名或不實資訊','Impersonation or misleading content')}</option><option>${bi('不當訊息或騷擾','Inappropriate content or harassment')}</option><option>${bi('素材權利疑慮','Media rights concern')}</option></select></label><label class="field">${bi('補充說明','Additional details')}<textarea name="detail" maxlength="1000"></textarea></label><button class="btn" type="submit">${bi('建立本機檢舉紀錄','Create local report')}</button></form><p>${bi('不會通知真人或正式客服。','No real person or support team will be notified.')}</p>`);return}
if(a==='recovery'){modal(`<h2 id="modal-title">${bi('帳號復原流程預覽','Account recovery preview')}</h2><p>${bi('正式流程：輸入 Email → 顯示不透露帳號是否存在的回應 → 寄發限時單次連結 → 驗證後恢復登入。變更信箱需重新驗證；其他裝置登出及 MFA 由身分服務執行。','Production flow: enter email → receive a non-enumerating response → receive an expiring one-time link → recover after verification. Email changes require re-verification; device revocation and MFA require the identity service.')}</p><p>${t('unconnected')}</p>`);return}
if(a==='export'){const data=JSON.stringify(state,null,2);const u=URL.createObjectURL(new Blob([data],{type:'application/json'}));const link=document.createElement('a');link.href=u;link.download='she-local-demo-data.json';link.click();setTimeout(()=>URL.revokeObjectURL(u),1000);return}
if(a==='logout'){state.session=false;persist();go('studio');return}if(a==='reset'||a==='delete-account'){modal(`<h2 id="modal-title">${bi('清除本機測試資料？','Clear local demo data?')}</h2><p>${bi('此操作只刪除這個瀏覽器的測試資料，無法刪除任何正式 SHE 帳號。','This removes demo data in this browser only. It cannot delete a live SHE account.')}</p><div class="form-actions">${button(t('cancel'),'close-modal','btn outline')}${button(bi('確認清除','Clear demo data'),'confirm-reset','btn')}</div>`);return}if(a==='confirm-reset'){const lang=state.lang;state={...structuredClone(defaults),lang};persist();closeModal();go('guide');toast(bi('已清除本機測試資料。','Local demo data cleared.'));return}
});
document.addEventListener('submit',e=>{const f=e.target;if(!f.id)return;e.preventDefault();const d=new FormData(f);if(f.id==='register-form'){captureForm();state.step=1;persist();render();return}if(f.id==='verify-form'){if(d.get('code')!=='246810'){$('.form-error',f).textContent=bi('測試碼不正確，請輸入 246810。','Incorrect demo code. Enter 246810.');return}state.step=2;persist();render();return}if(f.id==='roles-form'){state.reg.roles=['entrepreneur','contestant','creator','professional'].filter(k=>d.has(k));if(!state.reg.roles.length){$('.form-error',f).textContent=bi('請至少選擇一種身分。','Choose at least one role.');return}state.step=3;persist();render();return}if(f.id==='template-form'){state.draft={...state.draft,name:state.reg.name,roles:[...state.reg.roles],template:d.get('template'),location:d.get('location'),mainlang:d.get('mainlang')};state.session=true;state.step=0;audit(['完成註冊模擬','Completed demo registration']);persist();go('studio','','profile');return}if(f.id==='profile-form'){captureForm();state.status='draft';audit(['儲存專頁草稿','Saved profile draft']);persist();toast(bi('草稿已儲存；已核准版本保持獨立。','Draft saved; the approved snapshot remains separate.'));return}if(f.id==='settings-form'){for(const k of ['nationality','residence','timezone','phone'])state.draft[k]=String(d.get(k)||'');state.reg.consents.marketing=d.has('marketing');persist();toast(bi('設定已儲存在此瀏覽器。','Preferences saved in this browser.'));return}if(f.id==='post-form'){state.posts.unshift({title:String(d.get('title')),body:String(d.get('body')),language:d.get('language'),schedule:d.get('schedule'),status:'draft'});audit(['新增內容草稿','Created content draft']);persist();render();return}if(f.id==='invite-form'){state.invitations.unshift({name:String(d.get('name')),type:String(d.get('type')),detail:String(d.get('detail')),budget:String(d.get('budget')),location:String(d.get('location')),date:String(d.get('date')),timezone:String(d.get('timezone')),target:f.dataset.target,status:'pending'});audit(['建立本機合作邀請','Created local demo invitation']);persist();closeModal();toast(bi('模擬邀請已建立，可在工作台查看。沒有寄送訊息。','Demo invitation created. View it in the studio. No message was sent.'));return}if(f.id==='review-form'){state.reviewReason=String(d.get('reason'));state.status='changes';audit(['退回專頁修改','Requested profile changes']);persist();closeModal();render();return}if(f.id==='report-form'){audit(['建立本機檢舉紀錄（無外部通知）','Created local report (no notification)']);persist();closeModal();toast(bi('已建立本機檢舉紀錄，未通知客服。','Local report recorded. No support notification sent.'));return}if(f.id==='event-form'){closeModal();toast(bi('模擬登記完成，不會寄送通知。','Demo registration complete. No notifications will be sent.'));return}});
document.addEventListener('change',e=>{if(e.target.dataset.filter){state.filters[e.target.dataset.filter]=e.target.value;persist();const focus=e.target.id;render();document.getElementById(focus)?.focus()}if(e.target.id==='local-image'){const f=e.target.files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>5*1024*1024){toast(bi('請選擇 5MB 以內的 JPG、PNG 或 WebP。','Choose a JPG, PNG or WebP under 5 MB.'));e.target.value='';return}const u=URL.createObjectURL(f);const img=$('.editor-preview img');img.onload=()=>URL.revokeObjectURL(u);img.src=u;}});
let filterTimer;document.addEventListener('input',e=>{if(e.target.id==='people-q'){clearTimeout(filterTimer);const value=e.target.value,pos=e.target.selectionStart;filterTimer=setTimeout(()=>{state.filters.q=value;persist();render();const el=$('#people-q');el?.focus();el?.setSelectionRange(pos,pos)},250)}if(e.target.closest('#profile-form')){if(e.target.name==='name')$('#live-preview-name').textContent=e.target.value;if(e.target.name==='headline')$('#live-preview-headline').textContent=e.target.value}});
document.addEventListener('keydown',e=>{const dialog=$('.modal');if(!dialog)return;if(e.key==='Escape'){closeModal();return}if(e.key==='Tab'){const els=[...dialog.querySelectorAll('a[href],button:not([disabled]),input,select,textarea')].filter(el=>!el.hidden);const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
window.addEventListener('hashchange',()=>{captureForm();persist();closeModal();route=parseHash();render();window.scrollTo(0,0);$('#main')?.focus({preventScroll:true})});
render();

function magazinePayload(){return {lang:state.lang,page:route.page,id:route.id,people,session:state.session,draft:state.draft,follows:state.follows,bookmarks:state.bookmarks,motion:state.motion}}
function updateMagazine(){document.getElementById('magazine-frame')?.contentWindow?.postMessage({source:'she-preview-host',payload:magazinePayload()},location.origin)}
window.addEventListener('message',async e=>{const frame=document.getElementById('magazine-frame');if(!frame||e.origin!==location.origin||e.source!==frame.contentWindow||e.data?.source!=='she-magazine')return;const m=e.data;
if(m.action==='ready'){updateMagazine();return}
if(m.action==='route'){const allowed=['home','people','journal','tv','events','following','person','shop','member'];if(!allowed.includes(m.page))return;history.pushState({},'',href(m.page,m.id||''));route=parseHash();return}
if(m.action==='lang'){if(!['en','zh-Hant'].includes(m.lang))return;state.lang=m.lang;document.documentElement.lang=state.lang;persist();updateMagazine();return}
if(m.action==='navigate'){go(m.page,m.id||'');return}
if(m.action==='motion'){state.motion=!state.motion;persist();updateMagazine();return}
if(m.action==='follow'||m.action==='bookmark'){const key=m.action==='follow'?'follows':'bookmarks';state[key]=state[key].includes(m.id)?state[key].filter(x=>x!==m.id):[...state[key],m.id];persist();updateMagazine();return}
if(m.action==='invite'){invite(m.id);return}
if(m.action==='share'){try{await navigator.clipboard.writeText(location.origin+'/'+href('person',m.id));toast(bi('已複製專頁測試連結。','Demo profile link copied.'))}catch{toast(bi('請複製目前網址。','Copy the current URL.'))}return}
if(['video','gallery','event'].includes(m.action)){const proxy=document.createElement('button');proxy.dataset.action=m.action;if(m.id!==undefined)proxy.dataset.id=String(m.id);proxy.hidden=true;document.body.append(proxy);proxy.click();proxy.remove();return}
});
